import{_ as p,a0 as l,w as d,s as i,I as s,x as t,a1 as o,A as r,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"如何在Linux下监控系统温度 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux下监控系统温度 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux下监控系统温度 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux下监控系统温度 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/How to monitor system temperature on Linux","title":"如何在Linux下监控系统温度","tag":"201311","desc":""},"relativePath":"201311/How to monitor system temperature on Linux.md","filePath":"[post].md"}'),u={name:"201311/How to monitor system temperature on Linux.md"};function m(f,e,x,b,g,L){const n=l("Link");return d(),i("div",null,[e[21]||(e[21]=s("h1",{id:"如何在linux下监控系统温度",tabindex:"-1"},[t("如何在Linux下监控系统温度 "),s("a",{class:"header-anchor",href:"#如何在linux下监控系统温度","aria-label":"Permalink to “如何在Linux下监控系统温度”"},"​")],-1)),e[22]||(e[22]=s("p",null,"大多数情况下，你无需担心你的电脑温度。除非制造上的缺陷，否则硬件设计一般不会使其超过最高工作温度。但即使没有任何硬件故障，各种各样的软件问题也会导致硬件过热，例如，显卡驱动的严重bug，风扇控制程序的错误配置，CPU调频守护进程的故障，等等。",-1)),e[23]||(e[23]=s("p",null,"严重的过热可能会对硬件造成永久性的伤害，所以应当时刻小心系统上的任何过热问题。因此，如果有合适的温度监控系统，能在系统温度突然急速上升时，第一时间向用户发出警报，岂不美哉？",-1)),e[24]||(e[24]=s("p",null,[t("本教程，我将描述"),s("strong",null,"如何在Linux下监控系统温度"),t("。")],-1)),e[25]||(e[25]=s("p",null,"在Linux下有许多用户级工具可以检查和监控各种系统组件的温度。",-1)),s("p",null,[e[4]||(e[4]=t("例如",-1)),o(n,{href:"http://lm-sensors.org/"},{default:r(()=>[...e[0]||(e[0]=[t("lm-sensors",-1)])]),_:1}),e[5]||(e[5]=t("，它可以从硬件嵌入式传感器获取信息,以达到监测温度、电压、湿度和风扇的作用；还有",-1)),o(n,{href:"http://www.guzu.net/linux/hddtemp.php"},{default:r(()=>[...e[1]||(e[1]=[t("hddtemp",-1)])]),_:1}),e[6]||(e[6]=t(",它可以通过读取",-1)),o(n,{href:"http://en.wikipedia.org/wiki/S.M.A.R.T."},{default:r(()=>[...e[2]||(e[2]=[t("S.M.A.R.T.",-1)])]),_:1}),e[7]||(e[7]=t("参数来测量温度；今天我们要介绍的是",-1)),o(n,{href:"http://wpitchoune.net/blog/psensor/"},{default:r(()=>[...e[3]||(e[3]=[t("psensor",-1)])]),_:1}),e[8]||(e[8]=t("，这是一款前端图形化界面温度监测工具，能够可视化显示CPU、Nvidia/ATI/AMD各家显卡以及硬盘等多个硬件设备的温度。",-1))]),e[26]||(e[26]=a(`<p>接下来，我将描述如何设置psensor来监控CPUs和硬盘的温度。</p><h3 id="在linux-桌面系统中安装-psensor" tabindex="-1">在Linux 桌面系统中安装 psensor### <a class="header-anchor" href="#在linux-桌面系统中安装-psensor" aria-label="Permalink to “在Linux 桌面系统中安装 psensor###”">​</a></h3><p>使用psensor可视化显示系统温度，需要基于其他工具诸如lm-sensors和hddtemp等获得的数据。因此你需要在安装psensor的同时，一并安装这两款工具。</p><p>在Debian或Ubuntu下安装psensor:</p><pre><code>$ sudo apt-get install lm-sensors hddtemp psensor
</code></pre><p>在Ubuntu下还可以通过PPA仓库安装最新版本的psensor：</p><pre><code>$ sudo add-apt-repository ppa:jfi/ppa
$ sudo apt-get update
$ sudo apt-get install lm-sensors hddtemp psensor
</code></pre><p>在Fedora下安装psensor：</p><pre><code>$ sudo yum install lm_sensors hddtemp
$ sudo yum install gcc gtk3-devel GConf2-devel lm_sensors-devel cppcheck libatasmart-devel libcurl-devel json-c-devel libmicrohttpd-devel help2man libnotify-devel libgtop2-devel make
$ wget http://wpitchoune.net/psensor/files/psensor-0.8.0.3.tar.gz
$ tar xvfvz psensor-0.8.0.3.tar.gz
$ cd psensor-0.8.0.3
$ ./configure
$ make
$ sudo make install 
</code></pre><p>这里注意，由于需要GTK3库的支持，psensor无法与搭载GNOME2桌面的CentOs或RHEL 6兼容。</p><h3 id="在linux中配置-psensor" tabindex="-1">在Linux中配置 psensor <a class="header-anchor" href="#在linux中配置-psensor" aria-label="Permalink to “在Linux中配置 psensor”">​</a></h3><p>在启动 psensor之前，你需要先配置lm_sensors和hddtemp。</p><h4 id="lm-sensors-配置" tabindex="-1">lm_sensors 配置 <a class="header-anchor" href="#lm-sensors-配置" aria-label="Permalink to “lm_sensors 配置”">​</a></h4><p>运行以下命令，配置lm_sensors，每一项都选择YES。</p><pre><code>$ sudo sensors-detect 
</code></pre><p>这个命令将会探查和检测你硬件中嵌入的传感器(包括CPUs、储存控制器、I/O芯片)，然后自动决定系统中哪个驱动模块需要载入并监测其温度。</p><p>一旦传感器检测完成，你需要把检测到的驱动模块添加到/etc配置中，这样它们才可以在开机时自动加载。</p><p><img src="http://farm6.staticflickr.com/5476/10719567256_029533a588_z.jpg" alt="img"></p><p>在Debian或Ubuntu下，检测到的驱动模块将会被添加到/etc/modules。在Fedora下，驱动信息会添加到/etc/sysconfig/lm_sersors。</p><p>接下来，继续加载必要的模块，如下:</p><p>Ubuntu:</p><pre><code>$ sudo service module-init-tools start 
</code></pre><p>Debian:</p><pre><code>$ sudo /etc/init.d/kmod start
</code></pre><p>Fedora</p><pre><code>$ sudo service lm_sensors start 
</code></pre><h4 id="hddtemp-配置" tabindex="-1">hddtemp 配置 <a class="header-anchor" href="#hddtemp-配置" aria-label="Permalink to “hddtemp 配置”">​</a></h4><p>你还需要启动hddtemp，监控硬盘驱动器的温度。</p><p>运行下列命令，作为一个守护进程启动hddtemp。记得把“/dev/sda”替换成你系统上的硬盘驱动器。</p><pre><code>$ sudo hddtemp -d /dev/sda 
</code></pre><h3 id="用-psensor-监控系统温度" tabindex="-1">用 psensor 监控系统温度 <a class="header-anchor" href="#用-psensor-监控系统温度" aria-label="Permalink to “用 psensor 监控系统温度”">​</a></h3><p>要启动psensor监测温度，只需简单运行:</p><pre><code>$ psensor 
</code></pre><p>psensor窗口将显示一个可用的传感器列表，并将传感器中读出的温度可视化显示出来。你可以选择性地启用或禁用任意一个传感器。</p>`,34)),s("p",null,[o(n,{href:"http://www.flickr.com/photos/xmodulo/10719475225/"},{default:r(()=>[...e[9]||(e[9]=[s("img",{src:"http://farm8.staticflickr.com/7448/10719475225_f89b6f7191_z.jpg",alt:""},null,-1)])]),_:1})]),e[27]||(e[27]=s("p",null,"另外，你可以为每个传感器设置警报级别，这样当传感器温度超过某一阈值时，你就能得到通知了。",-1)),e[28]||(e[28]=s("p",null,[s("img",{src:"http://farm6.staticflickr.com/5534/10719755343_ba143454af_z.jpg",alt:"img"})],-1)),e[29]||(e[29]=s("p",null,"psensor默认使用的温度单位是“摄氏度”，最新的版本（0.7-0.8）支持在摄氏与华氏之间转换温度单位，如果你用的版本比较旧（例如0.6.x）并且不支持温度单位转换，Ubuntu用户可以通过PPA仓库来安装最新版的psensor，Debian用户则可以通过源代码来安装。",-1)),e[30]||(e[30]=s("hr",null,null,-1)),s("p",null,[e[11]||(e[11]=t("via: ",-1)),o(n,{href:"http://xmodulo.com/2013/11/monitor-system-temperature-linux.html"},{default:r(()=>[...e[10]||(e[10]=[t("http://xmodulo.com/2013/11/monitor-system-temperature-linux.html",-1)])]),_:1})]),s("p",null,[e[14]||(e[14]=t("译者：",-1)),o(n,{href:"https://github.com/Luoxcat"},{default:r(()=>[...e[12]||(e[12]=[t("Luoxcat",-1)])]),_:1}),e[15]||(e[15]=t(" 校对：",-1)),o(n,{href:"http://blog.csdn.net/tinyeyeser"},{default:r(()=>[...e[13]||(e[13]=[t("Mr小眼儿",-1)])]),_:1})]),s("p",null,[e[18]||(e[18]=t("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原创翻译，",-1)),o(n,{href:"http://linux.cn/"},{default:r(()=>[...e[17]||(e[17]=[t("Linux中国",-1)])]),_:1}),e[20]||(e[20]=t(" 荣誉推出",-1))])])}const C=p(u,[["render",m]]);export{k as __pageData,C as default};
